// === Tab: mySketch ===
let size = 512;
let siz = size-1;

let tension = 0.5;
let sympathy = 0.05;

let draggedNode = -1;

let colorray = new Array(16);

let px = new Array(size);
let py = new Array(size);
let vx = new Array(size);
let vy = new Array(size);
let ax = new Array(size);
let ay = new Array(size);

/////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowWidth, windowHeight);
  ellipseMode(RADIUS);
	fill(255, 128);

  for (let i = 1; i < siz; i++) {
    px[i] = width * i / size;
    py[i] = height/2 + randomGaussian() * 16;
  }

	px[0] = 16;
	py[0] = height/2;
	px[siz] = width - 64;
	py[siz] = height/2;

	changeColors();
}

/////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {
	for (let i = 1; i < siz; i++) {
		ax[i] = (px[i-1] + px[i+1] - px[i] - px[i]) * tension + (vx[i-1] + vx[i+1] - vx[i] - vx[i]) * sympathy;
		ay[i] = (py[i-1] + py[i+1] - py[i] - py[i]) * tension + (vy[i-1] + vy[i+1] - vy[i] - vy[i]) * sympathy;
	}

	for (let i = 1; i < siz; i++) {
		vx[i] += ax[i];
		vy[i] += ay[i];
		px[i] += vx[i];
		py[i] += vy[i];
	}

	if (draggedNode != -1) {
		px[draggedNode] = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
		py[draggedNode] = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	}


	background(32);
	noStroke();

	ellipse(px[0], py[0], 16, 16);
	ellipse(px[siz], py[siz], 16, 16);


	for (let i = 1; i < colorray.length + 1; i++) {
		stroke(colorray[i-1]);

		for (let node = 0; node < size-i; node++) {
			line(px[node], py[node], px[node+i], py[node+i]);
		}
	}
}

/////////////////////////////////////////////////////////////////////////////////////////////////

function mousePressed() {
	changeColors();

	draggedNode = -1;

	if (abs((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - px[0]) < 16    &&    abs((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - py[0]) < 16) {
		draggedNode = 0;
	}
	else if (abs((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - px[siz]) < 16    &&    abs((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - py[siz]) < 16) {
		draggedNode = siz;
	}
}

/////////////////////////////////////////////////////////////////////////////////////////////////

function mouseReleased() {
	draggedNode = -1;
}

/////////////////////////////////////////////////////////////////////////////////////////////////

function changeColors() {
	let r = random(256);
	let g = random(256);
	let b = random(256);

	for (let i = 0; i < colorray.length; i++) {
		colorray[i] = color(r + gauss(64), g + gauss(64), b + gauss(64), 128);
	}
}

/////////////////////////////////////////////////////////////////////////////////////////////////

function gauss(n) {
	return randomGaussian() * n;
}
